-- Generated from frozen candidate definitions. No DML; rejects edited owners before rollback.
declare n number; a clob; actual_hash varchar2(64); condition_value varchar2(4000);
 procedure fail(p_reason varchar2)is begin raise_application_error(-20886,'PICKER_TIME_INSTALLED_DRIFT:'||p_reason);end;
 procedure source_guard(p_name varchar2,p_type varchar2,p_hash varchar2)is begin
  dbms_lob.createtemporary(a,true);
  for s in(select TEXT from USER_SOURCE where NAME=p_name and TYPE=p_type order by LINE)loop dbms_lob.append(a,replace(s.TEXT,chr(13),''));end loop;
  a:=rtrim(ltrim(a,chr(10)||chr(9)||' '),chr(10)||chr(9)||' ');
  actual_hash:=rawtohex(sys.dbms_crypto.hash(a,sys.dbms_crypto.hash_sh256));dbms_lob.freetemporary(a);
  if actual_hash is null or actual_hash!=p_hash then fail(p_name||':'||p_type);end if;
 end;
 procedure constraint_guard(p_table varchar2,p_name varchar2,p_type varchar2,p_columns varchar2,p_condition varchar2,p_ref_table varchar2,p_ref_columns varchar2)is c USER_CONSTRAINTS%rowtype; cols varchar2(4000); rt varchar2(128);rc varchar2(4000);begin
  select * into c from USER_CONSTRAINTS where TABLE_NAME=p_table and CONSTRAINT_NAME=p_name;
  select listagg(COLUMN_NAME,',')within group(order by case when p_type='C'then null else POSITION end,COLUMN_NAME)into cols from USER_CONS_COLUMNS where CONSTRAINT_NAME=p_name;
  if c.CONSTRAINT_TYPE!=p_type or c.STATUS!='ENABLED'or c.VALIDATED!='VALIDATED'or c.DEFERRABLE!='NOT DEFERRABLE'or c.DEFERRED!='IMMEDIATE'or nvl(cols,'~')!=nvl(p_columns,'~')then fail(p_name||':SHAPE');end if;
  if p_type='C'then
   select regexp_replace(upper(replace(SEARCH_CONDITION_VC,'"','')),'[[:space:]]','')into condition_value from USER_CONSTRAINTS where CONSTRAINT_NAME=p_name;
   if condition_value is null or condition_value!=p_condition then fail(p_name||':CHECK');end if;
  elsif p_type='R'then
   select TABLE_NAME into rt from USER_CONSTRAINTS where CONSTRAINT_NAME=c.R_CONSTRAINT_NAME;
   select listagg(COLUMN_NAME,',')within group(order by POSITION)into rc from USER_CONS_COLUMNS where CONSTRAINT_NAME=c.R_CONSTRAINT_NAME;
   if c.R_OWNER!=user or rt!=p_ref_table or rc!=p_ref_columns or c.DELETE_RULE!='NO ACTION'then fail(p_name||':REFERENCE');end if;
  end if;
 exception when no_data_found then fail(p_name||':MISSING');end;
 procedure index_guard(p_table varchar2,p_name varchar2,p_columns varchar2,p_unique varchar2)is cols varchar2(4000);begin
  select count(*)into n from USER_INDEXES where TABLE_NAME=p_table and INDEX_NAME=p_name and INDEX_TYPE='NORMAL'and STATUS='VALID'and UNIQUENESS=p_unique and VISIBILITY='VISIBLE';if n!=1 then fail(p_name||':INDEX');end if;
  select listagg(COLUMN_NAME||':'||DESCEND,',')within group(order by COLUMN_POSITION)into cols from USER_IND_COLUMNS where INDEX_NAME=p_name;
  if cols!=p_columns then fail(p_name||':COLUMNS');end if;end;
